// Task board: single ownership enforced in code (plain JS)
function makeBoard() {
  const tasks = new Map();
  return {
    add(id, spec) { tasks.set(id, { ...spec, state: "open", owner: null }); },
    claim(id, agent) {
      const t = tasks.get(id);
      if (!t || t.state !== "open") return { ok: false, error: "unclaimable:" + id };
      t.state = "claimed"; t.owner = agent;
      return { ok: true };
    },
    complete(id, agent, outputRef) {
      const t = tasks.get(id);
      if (!t || t.owner !== agent) return { ok: false, error: "not-owner:" + id };
      t.state = "done"; t.outputRef = outputRef;
      return { ok: true };
    },
    skip(id, agent, reason) {
      const t = tasks.get(id);
      if (!t || (t.owner !== agent && t.state !== "open")) return { ok: false, error: "cannot-skip:" + id };
      t.state = "skipped"; t.owner = agent; t.skipReason = reason;
      return { ok: true };
    },
    backlog() { return [...tasks].filter(([, t]) => t.state === "open" || t.state === "claimed").map(([id]) => id); },
  };
}
// Claim races resolve in code (first claim wins); skips carry reasons always.

